t=np.arange(160);base=.012*np.sin(t/8)+.006*np.sin(t/19);stable=.025*np.sin(t/11);broken=stable+.0012*t;ax.plot(t,stable,color=ACCENT,label='stationary-looking spread');ax.plot(t,broken,color=BAD,label='drifting spread');ax.axhline(0,color=INK,lw=1);ax.set_xlabel('trading day');ax.set_ylabel('hedged log-price spread');ax.legend(fontsize=8);ax.set_title('Similar co-movement can hide different equilibria',loc='left')
